class Solution {
    public char kthCharacter(int k) {
        int shifts = Integer.bitCount(k - 1);
        return (char) ('a' + (shifts % 26));
    }
}

var kthCharacter = function(k) {
    let n = k - 1;
    let shifts = 0;
    while (n > 0) {
        shifts += (n & 1);
        n >>= 1;
    }
    return String.fromCharCode(97 + (shifts % 26));
};
